func (s *Store) RevokeAPIKey(orgID, id string, now time.Time) (APIKey, error) {
	s.mu.Lock()
	defer s.mu.Unlock()
	k, ok := s.apiKeys[id]
	if !ok || k.OrgID != orgID {
		return APIKey{}, ErrNotFound
	}
	if k.RevokedAt == nil {
		t := now.UTC()
		k.RevokedAt = &t
		s.apiKeys[id] = k
	}
	return k, nil
